export function fft(re,im){const n=re.length;for(let i=1,j=0;i<n;i++){let b=n>>1;for(;j&b;b>>=1)j^=b;j^=b;if(i<j){[re[i],re[j]]=[re[j],re[i]];[im[i],im[j]]=[im[j],im[i]];}}for(let len=2;len<=n;len<<=1){const ar=Math.cos(-2*Math.PI/len),ai=Math.sin(-2*Math.PI/len);for(let i=0;i<n;i+=len){let wr=1,wi=0;for(let j=0;j<len/2;j++){const u=i+j,v=u+len/2,tr=wr*re[v]-wi*im[v],ti=wr*im[v]+wi*re[v];re[v]=re[u]-tr;im[v]=im[u]-ti;re[u]+=tr;im[u]+=ti;const x=wr*ar-wi*ai;wi=wr*ai+wi*ar;wr=x;}}}}
export const db=p=>p>0?10*Math.log10(p):-Infinity;
export function analyze(pcm,sr,low,high,duration,start=0){if(!(pcm instanceof Float32Array)||!Number.isFinite(sr)||sr<8000||sr>192000)throw Error('无效音频');const n=2**Math.ceil(Math.log2(sr/6)),hop=n/2,first=Math.round(start*sr),length=Math.round(duration*sr),end=first+length;if(first<0||end>pcm.length+1||length<n)throw Error('片段长度不足');const k0=Math.max(1,Math.ceil(low*n/sr)),k1=Math.min(n/2,Math.floor(high*n/sr));if(k0>k1)throw Error('频段比 FFT 频率分辨率更窄，请放宽频段');const w=new Float64Array(n);let u=0;for(let i=0;i<n;i++){w[i]=.5-.5*Math.cos(2*Math.PI*i/(n-1));u+=w[i]*w[i];}const positions=[];for(let pos=first;pos+n<=end;pos+=hop)positions.push(pos);const last=end-n;if(positions.at(-1)!==last)positions.push(last);const powers=[],re=new Float64Array(n),im=new Float64Array(n);const spectrum=new Float64Array(n/2+1);let clipped=0,samplePeak=0;for(let i=first;i<end&&i<pcm.length;i++){const a=Math.abs(pcm[i]);if(a>=.999)clipped++;samplePeak=Math.max(samplePeak,a);}for(const pos of positions){for(let i=0;i<n;i++){re[i]=(pcm[pos+i]||0)*w[i];im[i]=0;}fft(re,im);let p=0;for(let k=k0;k<=k1;k++){const e=(re[k]*re[k]+im[k]*im[k])*(k===n/2?1:2)/(n*u);spectrum[k]+=e;p+=e;}powers.push(p);}const sorted=[...powers].sort((a,b)=>a-b),q=(p)=>{const i=(sorted.length-1)*p,a=Math.floor(i);return sorted[a]+(sorted[Math.ceil(i)]-sorted[a])*(i-a);};let maxbin=k0;for(let k=k0;k<=k1;k++)if(spectrum[k]>spectrum[maxbin])maxbin=k;const overall=powers.reduce((a,b)=>a+b,0)/powers.length;const weights=positions.map((p,i)=>{const left=i===0?first:(positions[i-1]+p+n)/2,right=i===positions.length-1?end:(p+positions[i+1]+n)/2;return(right-left)/sr;});return{weights,overall:db(overall),peak:db(sorted.at(-1)),quiet:db(q(.1)),overallPower:overall,peakPower:sorted.at(-1),quietPower:q(.1),powers,frameCount:powers.length,windowSeconds:n/sr,hopSeconds:hop/sr,resolution:sr/n,effectiveLow:k0*sr/n,effectiveHigh:k1*sr/n,peakFrequency:maxbin*sr/n,clipped,samplePeak,duration,start,sampleRate:sr};}
export function selfTest(){const sr=48000,pcm=new Float32Array(sr*2);for(let i=0;i<pcm.length;i++)pcm[i]=.1*Math.sin(2*Math.PI*1000*i/sr);const a=analyze(pcm,sr,500,1500,2),b=analyze(pcm,sr,20,200,2);for(let i=pcm.length/2;i<pcm.length;i++)pcm[i]*=5;const c=analyze(pcm,sr,500,1500,2);const tests=[['已知正弦 RMS ≈ −23.01 dBFS',Math.abs(a.overall-(-23.0103))<.02,a.overall],['带外抑制超过 60 dB',b.overall<a.overall-60,b.overall-a.overall],['峰时 > 平均 > 安静时',c.peak>c.overall&&c.overall>c.quiet,c.peak-c.quiet],['平均功率约增加 11.14 dB',Math.abs((c.overall-a.overall)-10*Math.log10(13))<.4,c.overall-a.overall]];return tests.map(([name,pass,value])=>({name,pass,value}));}
export function floorValue(s){const m=s.match(/[零〇一二两三四五六七八九十百\d]+(?=楼|层)/);if(!m)return null;if(/^\d+$/.test(m[0]))return Number(m[0]);const d={零:0,〇:0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};let result=0,current=0;for(const c of m[0]){if(c==='十'){result+=(current||1)*10;current=0;}else if(c==='百'){result+=(current||1)*100;current=0;}else current=d[c];}return result+current;}
export function naturalCompare(a,b){const x=floorValue(a.label),y=floorValue(b.label);return x!==null&&y!==null&&x!==y?x-y:a.label.localeCompare(b.label,'zh-CN',{numeric:true});}

export function groupFrames(r,threshold){let ep=0,qp=0,et=0,qt=0,ec=0,qc=0;const flags=[];r.powers.forEach((p,i)=>{const w=r.weights[i],event=db(p)>=threshold;flags.push(event);if(event){ep+=p*w;et+=w;ec++;}else{qp+=p*w;qt+=w;qc++;}});return{...r,overall:db((ep+qp)/(et+qt)),event:et>0?db(ep/et):null,quiet:qt>0?db(qp/qt):null,eventSeconds:et,quietSeconds:qt,eventCount:ec,quietCount:qc,flags,threshold};}
